import {marasenExtraInteract} from './marasen-activities-ui.js?v=0.90.48';
import {MARASEN_RECORDS,MARASEN_BRANCHES,MARASEN_TRAINERS,VERDANT_ROAD,marasenRoute} from './marasen-data.js?v=0.90.48';
import * as r from './marasen-rules.js?v=0.87.0';
export function marasenInteract(id,a){
 if(marasenExtraInteract(id,a))return true;
 const {state,room,AREA_GATES,line,showDialogue,openModal,$,document,warp,rewardTransaction,escapeHTML,challengeTrainer,startWild,shop}=a;
 const gate=AREA_GATES[room]?.find(g=>g.id===id),q=r.marasenState(state),branch=MARASEN_BRANCHES[room];
 const say=(name,text,portrait=null)=>showDialogue([line(name,text,portrait)]),commit=change=>{const okay=rewardTransaction(change);if(okay)a.buildMarkers();return okay;},again=()=>marasenInteract(id,a);
 const dialogue=(name,texts,portrait,after)=>showDialogue(texts.map(t=>line(name,t,portrait)),after);
 const record=(title,texts)=>openModal(title,texts.map(t=>'<p>'+escapeHTML(t)+'</p>').join(''));
 if(id==='cs-boundary'){
  if(!r.marasenUnlocked(state))say('Marasen road','Settle Ismail’s challenge and fate before the column moves on.');
  else dialogue('The green road',['The blackened slope falls behind you. Water moves through stone channels under trees that were never cut for a siege. Ismail’s forestry orders are still nailed beside the sluice.','Whether Ismail lives or dies, his years of careful work remain in this valley. The road to Marasen is open.'],null,()=>void warp('greenCut',3,17,'right'));return true;
 }
 if(gate?.action==='marasen-side-entry'){
  const key=id.split('-')[1];if(key==='peach'&&!r.peachUnlocked(state)){say('Uncut peach track','The branches turn you back. A worn stone shows a poisoned hunter beneath a flooded fort, and a small figure fleeing past a traveller. Return to the Sunken Fort, descend to its bottom floor and resolve Wei’s unique encounter. Then return to Pearlwater Falls and take this north trail. The east road towards Marasen stays open.');return true;}void warp(gate.to,...gate.arrival);return true;
 }
 if(gate?.action==='marasen-expedition'){
  if(!r.passageOpen(state,branch.quest,branch.stage))say('Expedition passage',r.marasenObjective(state,room).text+'. The west return arch stays open.');else void warp(gate.to,...gate.arrival);return true;
 }
 if(gate?.action==='marasen-fort'){
  if(q.walk.length<3)say('Civic fort','Before entering: '+r.marasenObjective(state,room).text);else void warp(gate.to,...gate.arrival);return true;
 }
 if(gate?.action==='marasen-fort-hall'){
  if(!r.defeated(state,'TRN-MR-GATE')||!r.questState(state,'fort').solved)say('Archive lock',r.marasenObjective(state,room).text);else void warp(gate.to,...gate.arrival);return true;
 }
 if(id==='marasen-next'){say('Botrune road',state.fates?.['LDR-05']?'The dispatch riders have gone towards Botrune. That chapter is not yet open. Marasen, the green road and all earlier regions remain available.':'Settle Khalid’s challenge before following the column beyond Marasen.');return true;}
 if(id==='area-sign'&&(VERDANT_ROAD.some(x=>x[0]===room)||branch)){
  const route=marasenRoute(room),pages=['Cossenne’s protected headwaters feed this road. Nursery margins, uncut canopy and controlled spillways explain the biodiversity. A single noticeboard records this stretch; the small expedition tablets carry the puzzle clues.'];
  pages.unshift('Directions: '+r.marasenObjective(state,room).text);
  if(route.tables.length)pages.push('Wild Abyssals appear in the tall wildflower meadows off the path. The pale earth paths and wooden crossings are safe from wild encounters. Short grass, tended garden beds and the settlement are safe too.');
  if(route.tables.length)for(const t of route.tables)pages.push(t.phase+': '+t.slots.map(s=>a.species(s.species_id).name+' '+s.weight+'% · Lv '+s.min_level+'–'+s.max_level).join('; '));
  if(branch?.quest)pages.push('Expedition: '+branch.quest+'. Read the site accounts in order. Return paths stay open; mistakes in mechanisms can be reset.');record(route.area.name,pages);return true;
 }
 const keeper=id.match(/^mr-(mill|peach|darius)-keeper$/);
 if(keeper){const key=keeper[1],p=r.questState(state,key),name=key==='mill'?'Hugh atte Mill':key==='darius'?'Maryam bint Salim':'Peach orchard marker',portrait=key==='mill'?'REV-HUGH':key==='darius'?'REV-MARYAM':null;
  const briefs={mill:'The mill’s regulating stones were taken for army wagons. Read the race diagram, restore the coupled controls in the root vault, then face Hugh’s milling challenge and allocate the flour. Reward: 3,000 doubloons, plus a permanent choice of supplies.',peach:'The fleeing Liubeirow left a track beneath the falls. Read the three witness pools, reconstruct the oath in the next clearing, then approach its spring. This unlocks a unique encounter; defeating it is permanent.',darius:'Darius has captured Tellurion. Before approaching him, restore the spillway, help Alice send the last families out of the flood line, then climb to the crown reservoir. Defeating Darius releases Tellurion for a separate capture encounter. Evacuation reward: 2,500 doubloons and two Emergency Evacs. His final reckoning lies beyond this chapter.'};
  showDialogue([{...line(name,p.accepted?'Your expedition is recorded. '+r.marasenObjective(state,room).text:briefs[key],portrait),choices:[{text:p.accepted?'Continue the expedition.':'Accept the expedition.',action:()=>{if(!p.accepted)commit(()=>r.acceptMarasenQuest(state,key));}},{text:'Return later.',action:()=>{}}]}]);return true;
 }
 const rec=id.match(/^mr-(mill|peach|darius)-record-(\d)$/);
 if(rec){const key=rec[1],n=Number(rec[2]),p=r.questState(state,key);if(!p.accepted){say('Site account',r.marasenObjective(state,room).text);return true;}if(!p.records.includes(n)&&n>0&&!p.records.includes(n-1)){say('Site account',r.marasenObjective(state,room).text);return true;}if(!p.records.includes(n)&&!commit(()=>r.readMarasenRecord(state,key,n)))return true;if(!p.records.includes(n)){say('Site account','Read the earlier record before interpreting this page.');return true;}const page=MARASEN_RECORDS[key][n];record(page[0],[...page.slice(1),'Copied into Journal → Recorded site tablets. You can also return to this stone tablet and press A to read it again.']);return true;}
 const control=id.match(/^mr-(mill|darius|fort)-control$/);
 if(control){const key=control[1],p=r.questState(state,key);if(key!=='fort'&&(!p.accepted||!p.records.includes(1))){say('Coupled controls',r.marasenObjective(state,room).text);return true;}if(key==='fort'&&!r.defeated(state,'TRN-MR-GATE')){say('Archive lock',r.marasenObjective(state,room).text);return true;}
  const names=key==='mill'?['Root','Wheel','Overflow']:key==='darius'?['Orchard','Quarry','Road']:['Headwater','Nursery','Town'];
  const clue=key==='fort'?'Six measures are written in the city account. Headwater takes half; Nursery takes one; Town takes what remains. Each handle advances its own channel by one and the next channel by two, wrapping around. Indicators run 0–6. Read the city’s household accounts before turning.':'Use the allocation described in the site accounts. Each handle advances its own channel by one and the next channel by two; the last also advances the first. Indicators run 0–6. Read the resulting flows, not the number of turns.';
  openModal(key==='fort'?'The household allocation lock':'Restore the coupled channels','<p>'+clue+'</p><p><b>Current flows:</b> '+p.rings.map((v,i)=>names[i]+' '+v).join(' · ')+'</p><p>'+(p.solved?'The mechanism is stable and its passage is open.':'A wrong attempt costs no items. The gate opens only when the allocation is safe.')+'</p><div class="modal-actions">'+names.map((name,i)=>'<button data-mr-wheel="'+i+'" '+(p.solved?'disabled':'')+'>Turn '+name+'</button>').join('')+'<button id="mr-reset" '+(p.solved?'disabled':'')+'>Reset mechanism</button></div>');
  for(const el of document.querySelectorAll('[data-mr-wheel]'))el.onclick=()=>{if(commit(()=>r.turnMarasenWheel(state,key,Number(el.dataset.mrWheel))))again();};$('#mr-reset').onclick=()=>{if(commit(()=>r.turnMarasenWheel(state,key,0,true)))again();};return true;
 }
 if(id==='mr-peach-bells'){const p=r.questState(state,'peach');if(!p.records.includes(2)){say('Oath bells',r.marasenObjective(state,room).text);return true;}openModal('The unclaimed fourth seat','<p>Three bells bear titles: Healer, Shield, Caller. Reconstruct the outward journey and the return described by the witness pools. The stone judges all six strokes together and gives no feedback about individual strokes.</p><p>'+escapeHTML(p.solved?'The oath is complete. The spring path is open.':'Your candidate: '+(p.order.join(' → ')||'none')+'. '+(p.order.length===6?'The full oath did not answer. Read the accounts and try another whole sequence.':'Complete all six strokes before the stone judges it.'))+'</p><div class="modal-actions">'+['healer','shield','caller'].map(b=>'<button data-mr-bell="'+b+'" '+(p.solved?'disabled':'')+'>'+b+'</button>').join('')+'<button id="mr-bell-reset" '+(p.solved?'disabled':'')+'>Clear candidate</button></div>');$('#mr-bell-reset').onclick=()=>{if(commit(()=>r.resetPeachBells(state)))again();};for(const el of document.querySelectorAll('[data-mr-bell]'))el.onclick=()=>{if(commit(()=>r.ringPeachBell(state,el.dataset.mrBell)))again();};return true;}
 if(id==='mr-mill-choice'){const p=r.questState(state,'mill');if(p.claimed){say('Hugh atte Mill','Your allocation is recorded: '+p.choice+'. The mill’s prize has been paid.','REV-HUGH');return true;}if(!p.solved||!p.records.includes(2)||!r.defeated(state,'TRN-MR-HUGH')){say('Hugh atte Mill',r.marasenObjective(state,room).text,'REV-HUGH');return true;}showDialogue([{...line('Hugh atte Mill','Both choices are permanent. Both include 3,000 doubloons. Kitchens: twelve Hearty Rations and six Poultices. Nurseries: five Training Tonics and one Life Ember. The other households must wait for the next milling.','REV-HUGH'),choices:[{text:'Allocate to the kitchens.',action:()=>commit(()=>r.chooseMill(state,'kitchens'))},{text:'Allocate to the nurseries.',action:()=>commit(()=>r.chooseMill(state,'nurseries'))},{text:'Decide later.',action:()=>{}}]}]);return true;}
 if(id==='mr-evacuate'){if(!r.questState(state,'darius').solved||!r.questState(state,'darius').records.includes(2)||!r.defeated(state,'TRN-MR-ALICE'))say('Alice atte Ford',r.marasenObjective(state,room).text,'REV-ALICE');else if(r.questState(state,'darius').evacuated)say('Alice atte Ford','Every household on my list is beyond the warning line. The upper road is open.','REV-ALICE');else dialogue('Alice atte Ford',['The quarry spillway is running. Hugh’s last cart crosses the bridge with the youngest children asleep beneath the flour cloth. Farid strikes the warning bell; Maryam answers from the upper path.','No family is a symbol on a map now. They are all named, and all accounted for. The crown reservoir road is open. Received 2,500 doubloons and two Emergency Evacs.'],'REV-ALICE',()=>commit(()=>r.evacuateValley(state)));return true;}
 if(id==='mr-peach-encounter'||id==='mr-tellurion-encounter'){
  const key=id==='mr-peach-encounter'?'peach':'tellurion';if(q.encounters[key])say('Quiet shelf',q.encounters[key]==='captured'?'This unique partner already travels with your expedition.':'The creature has died. This encounter will not return.');else if(!r.canMeetMarasen(state,key))say('Quiet shelf','Finish this expedition’s records and challenges before approaching. A unique creature already in your expedition or memorial cannot appear again.');else showDialogue([{...line(key==='peach'?'Liubeirow':'Maryam bint Salim',key==='peach'?'Liubeirow steps away from the spring. This is a unique encounter. Defeating it is permanent; you may offer capture food during battle.':'Tellurion’s bridle is open and its wounds have been tended. Darius will not command it again. It may choose a new companion, but it will first test you. Capture food works in this unique encounter.','REV-MARYAM'),choices:[{text:'Approach the creature.',action:()=>{let spec;if(commit(()=>spec=r.encounterSpec(state,key))&&spec)startWild(spec);}},{text:'Prepare and return.',action:()=>{}}]}]);return true;
 }
 const trainer=MARASEN_TRAINERS.find(t=>t.id===id);
 if(trainer){if(id==='TRN-MR-HUGH'&&!r.questState(state,'mill').solved)say('Hugh atte Mill',r.marasenObjective(state,room).text,'REV-HUGH');else if(id==='TRN-MR-FARID'&&!r.questState(state,'darius').accepted)say('Farid ibn Yunus',r.marasenObjective(state,room).text,'REV-FARID');else if(id==='TRN-MR-ALICE'&&!r.questState(state,'darius').solved)say('Alice atte Ford',r.marasenObjective(state,room).text,'REV-ALICE');else if(id==='TRN-MR-DARIUS'){
   if(!r.questState(state,'darius').evacuated)say('Darius',r.marasenObjective(state,room).text,'REV-DARIUS');else if(r.defeated(state,id))dialogue('Darius',['I will not pretend the valley’s fear was an accident. I meant them to be afraid. I wanted the men ordering the next attack to understand what the people below them already live with.','You stopped this demonstration. That does not make either army merciful. Maryam is taking Tellurion to the garden shelf. Let it choose whom to follow.','I need to hear my own people before I ask them to follow me further. We will meet again.'],'REV-DARIUS');else dialogue('Maryam bint Salim',['Darius. I treated the workers you ordered onto that scaffold. Tell me which of them was supposed to be proof that your threat was real.','He turns from the dam. Tellurion’s bridle tightens, and roots split the survey stones. His five ordinary partners move in front of it.','Darius answers quietly: I tried asking men who bless hunger to pity it. I tried feeding the people they had written off. What do you offer for the day the next column marches?'],'REV-MARYAM',()=>challengeTrainer(trainer));
  }else challengeTrainer(trainer);return true;}
 if(id==='mr-leader'){
  const leader=MARASEN_TRAINERS.find(t=>t.id==='LDR-05');if(state.fates?.['LDR-05']==='SPARED')showDialogue([{...line(leader.name,'The canal watch still trains. A supervised rematch pays experience and doubloons again. I remain under your officer’s supervision.','LDR-05'),choices:[{text:'Arrange a rematch.',action:()=>a.rematch(leader)},{text:'Later.',action:()=>{}}]}]);else if(state.fates?.['LDR-05'])say('Assembly hall','Khalid’s seat is empty. The household clerks keep the water accounts.');else if(!r.marasenLeaderReady(state))say(leader.name,r.marasenObjective(state,room).text,'LDR-05');else challengeTrainer(leader);return true;
 }
 if(id==='mr-water'){dialogue('Canal households',['The trees did not grow because an army won a battle. Ismail protected the headwater. Khalid kept the channel crews paid through the winter. Children planted the banks the collectors wanted cleared.','Six measures are recorded on the fort’s allocation dial. The headwater margin receives half, the nursery receives one, and the town receives the rest. Nobody gets to take the full stream.'],null,()=>commit(()=>r.recordMarasenWalk(state,'water')));return true;}
 if(id==='mr-levy'){dialogue('Levy clerk',['The column wants Marasen’s seed grain. First Light calls it a contribution; our council called the previous collection a sacred duty. The receipts promise repayment after victory.','Farid has copied the household lists. Darius took our quarry survey. Both say they want the fighting to end. I would like someone to ask who eats between now and then.'],null,()=>commit(()=>r.recordMarasenWalk(state,'levy')));return true;}
 if(id==='mr-letters'||id==='mr-archive-service'){dialogue('Trade’s forwarding box',['A letter is addressed to Aimon in Trade’s hand. Pate has added a warning beneath it, pressing hard enough to mark the next sheet.','“We reached Marasen together. There are men here who think winning the war will make everything we have done bearable. Pate says we should be among them. I am not sure he still believes it. We have been sent on ahead towards Botrune. The Scribes’ Road crosses an exposed thunderplain. The conductors have been stripped, and the next crossing will be dangerous. Pate says to take the shelters and never rush the pass to catch us. If you follow, do not follow an order just because it sounds like ours.”',state.humanLives?.['CHR-TRADE']?.historicalDeath?'The clerk lets you keep another copy. The ink belongs to a time before the platform in Botrune.':'The clerk lets you keep a copy. When this letter was written, Pate and Trade were travelling together towards Botrune.'],null,()=>commit(()=>r.recordMarasenWalk(state,'letters')));return true;}
 if(id==='mr-farid-city'){say('Farid ibn Yunus',r.defeated(state,'TRN-MR-DARIUS')?'Alice kept the names. Maryam kept asking who would be hurt. Hugh kept feeding people while we argued. Darius has gone to listen to them. I cannot promise what he will decide.':'The valley is green because someone did boring work for years. Darius thinks one demonstration can protect it forever. I want him to be right. I am frightened of what happens if he is not.','REV-FARID');return true;}
 if(id==='mr-seed-service'){const p=r.questState(state,'mill'),done=q.seedExchange;showDialogue([{...line('Seed exchange',done?'Your seed shipment is recorded. Come back to the expedition paths for further work.':'The mill needs six Trail Bread for its travelling workers. One shipment earns three Hearty Rations and 800 doubloons. This delivery pays once per expedition.'),choices:[{text:done?'Shipment complete.':'Deliver six Trail Bread.',action:()=>{if(!done&&(state.bread||0)>=6)commit(()=>{state.bread-=6;state.heartyFood=(state.heartyFood||0)+3;state.money=(state.money||0)+800;r.marasenState(state).seedExchange=true;});}},{text:'Browse supplies.',action:shop}]}]);return true;}
 if(id==='mr-mill-service'){const day=new Date().toISOString().slice(0,10);if(q.serviceDays.includes(day)){say('Mill sorting bench','Today’s seed grading is complete. Your payment is already recorded.');return true;}const target=['heavy','light','heavy','light'];q.sorting??=[];openModal('Seed grading · daily paid work','<p>Sort the four samples from left to right. The first and third sink in the water cup; the others float. Use the miller’s heavy/light trays. A mistake clears the tray. Completing the lot pays 500 doubloons once per day.</p><p>Tray: '+escapeHTML(q.sorting.join(' · ')||'empty')+'</p><button id="mr-heavy">Heavy tray</button><button id="mr-light">Light tray</button>');for(const type of ['heavy','light'])$('#mr-'+type).onclick=()=>{if(commit(()=>{const current=r.marasenState(state);current.sorting??=[];if(current.serviceDays.includes(day))return;if(target[current.sorting.length]!==type)current.sorting=[];else current.sorting.push(type);if(current.sorting.length===4){current.serviceDays.push(day);state.money=(state.money||0)+500;current.sorting=[];}}))again();};return true;}
 if(id==='mr-apothecary-service'){say('Waterside apothecary','The next fight can wait. Walter restores living partners outside. Specialist medicines and stronger capture foods are stocked at this counter.');return true;}
 return false;
}


